		nl.DEVLINK_ESWITCH_INLINE_MODE_NETWORK:   "network",
		nl.DEVLINK_ESWITCH_INLINE_MODE_TRANSPORT: "transport",
	}
	if inlineMode[mode] == "" {
		return "unknown"
	}
	return inlineMode[mode]
}

