	}
	sb.WriteString("Stack:\n")
	sb.WriteString(wrapLinesWithTabPrefix(g.CurrentStack))
	return sb.String()
}

func NewGoLearnError(err error, description string) *GoLearnError {
	return &GoLearnError{
		WrappedError: err,
		CurrentStack: string(debug.Stack()),
		Description:  description,
	}
}

