// Config contains configuration data.
type Config struct {
	items map[string]string
}

// New creates a new Config.
func New() *Config {
	return &Config{
		items: make(map[string]string),
	}
}

// Load reads configuration from a file.
func (cfg *Config) Load(filename string) error {
	f, err := os.Open(filename)
	if err != nil {
		return fmt.Errorf("failed to open config file %q: %w", filename, err)
	}
	defer f.Close()

	return cfg.Parse(f)
}

// LoadDefault searches for a configuration file in common locations.
func (cfg *Config) LoadDefault() error {
	homeDir, err := os.UserHomeDir()
	if err != nil {
		return fmt.Errorf("failed to get user home directory: %w", err)
	}

