func password(client net.Conn, server net.Listener) bool {
	var entered string
	var i int

	for {
		fmt.Fprint(client, "PASSWORD")
		fmt.Fscan(client, &entered)
		i = i + 1

		if entered != passwordstr {
			log.Warnf("Host %s failed password (%s) (%s)", client.RemoteAddr(), string(i), entered)
			if i > 2 {
				return false
			}
		} else {
			return true
		}
	}

}

