	if err := genmodel.LoadEngine(dir, engineName); err != nil {
		return fmt.Errorf("failed to load engine '%s' from '%s': %w", engineName, dir, err)
	}

	fmt.Printf("Engine '%s' loaded from '%s'\n", engineName, dir)
	return nil
}

