// 绘制文本
func (this *Html2Image) DrawText(text string) {
	r := []rune(text)
	for len(r) > 0 {
		if this.IsOver(r) {
			this.NewBr()
		}
		// 绘制一行
		this.gc.FillStringAt(string(r), this.x, this.y)
		// 移动x
		width := this.gc.FillStringAt(string(r), 0, 0)
		this.x += width
		// 移除已经绘制的
		r = r[len(r):]
	}
}

