// 渲染文本
func (this *Html2Image) RenderText(text string) {
	runes := []rune(text)
	var line []rune
	for _, r := range runes {
		line = append(line, r)
		if this.IsOver(line) {
			this.RenderLine(string(line[:len(line)-1]))
			line = []rune{r}
		}
	}
	if len(line) > 0 {
		this.RenderLine(string(line))
	}
}

// 渲染一行
func (this *Html2Image) RenderLine(text string) {
	this.gc.FillStringAt(text, this.x, this.y)
	width := this.gc.FillStringAt(text, 0, 0)
	this.x += width
}

