func (this *Html2Image) setImage(path string, x, y float64) {
    f1, err := os.Open(path)
    if err != nil {
    	return;
        panic(err)
    }

    var m1 image.Image
	_, ext := lea.SplitFilename(path)
    if ext == ".png" {
	    m1, err = png.Decode(f1)
    } else if ext == ".gif" {
	    m1, err = gif.Decode(f1)
    } else if ext == ".jpg" {
	    m1, err = jpeg.Decode(f1)
    }
	if err != nil {
	    return
        panic(err)
    }

    this.gc.Translate(x, y)
    this.gc.DrawImage(m1)
    this.gc.Translate(-x, -y)
}

