func requestConsent(w http.ResponseWriter, r *http.Request) {
	sess, err := request.Session(r)
	if err != nil {
		http.Error(w, erro.Wrap(err).Error(), http.StatusInternalServerError)
		return
	}

	authReq, err := request.AuthRequest(r)
	if err != nil {
		http.Error(w, erro.Wrap(err).Error(), http.StatusInternalServerError)
		return
	}

	if authReq.Scope == nil || len(*authReq.Scope) == 0 {
		http.Error(w, erro.New("no scope specified").Error(), http.StatusBadRequest)
		return
