func requestConsent(w http.ResponseWriter, r *http.Request, sess request.Session, clientID, redirectURI, state string, scopes []string) error {
	// 認証状態をセッションに保存する。
	if err := sess.Save(r.Context(), clientID, redirectURI, state, scopes); err != nil {
		return erro.Wrap(err)
	}

	// 許可画面にリダイレクトする。
	http.Redirect(w, r, "/consent?session_id="+sess.ID(), http.StatusFound)
	return nil
}

