func (dic *Dictionary) Elements() []KeyValueElement {
	elements := make([]KeyValueElement, 0, len(dic.elements))
	for key, value := range dic.elements {
		elements = append(elements, KeyValueElement{Key: key, Value: value})
	}
	return elements
}

// Get retrieves the value associated with a given key
func (dic *Dictionary) Get(key KeyElement) (ValueElement, error) {
	if !dic.Contains(key) {
		return nil, ErrKeyNotFound
	}
	return dic.elements[key], nil
}

// IsEmpty checks if the dictionary is empty
func (dic *Dictionary) IsEmpty() bool

